head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > class]<br/>Column 영역에 적용하려는 클래스의 이름을 설정합니다.",
    "validation" : [
        "Column 영역에 적용하려는 클래스의 이름을 설정합니다.",
        "문자열 설정 시, CSS 파일이나 style 블럭에 정의된 클래스 이름을 공백으로 구분하여 설정합니다.",
        "웹표준의 class 속성과 동일한 기능을 제공합니다.",
        "렌더링 과정에서 웹스퀘어의 기본 클래스가 추가로 설정될 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_class.setSelectedIndex(2);

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 설정
    //  - class 는 Column 단위 속성이며 dynamic N 이므로 렌더 시점에만 설정한다.
    //  - Header / Body / Footer 의 1번째 Column 에만 class 를 설정하고, 2번째 Column 은 미설정 (비교용)
    let cClass = con_class.getValue();
    let lblClass = (cClass === '') ? '미설정' : cClass;
    let attrClass = (cClass === '') ? '' : ' class="' + cClass + '"';

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Header / Body / Footer 의 1번째 Column 에만 class 설정, 2번째 Column 은 미설정 (비교용)\n[현재] column class = ' + lblClass + '\n[확인] 클래스 확인 -> 영역별 [렌더] 줄(설정 class, 배경색, 글자색)\n[확인] 설정 Column 도 기본 테두리/굵기 유지 (옆 미설정 Column 과 비교)"', '', 'label1');

    // dataList 생성 (col1~col4 / 4행)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:600px;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column1" value="name1"' + attrClass + '></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col1" value=""' + attrClass + '></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="row3">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="footer_col1" value="footer1"' + attrClass + '></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="footer_col2" value="footer2"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="footer_col3" value="footer3"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="footer_col4" value="footer4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// Column 요소의 설정 class(cc_ 접두사), 배경색, 글자색을 한 줄로 반환
scwin.getColumnInfo = function (elem) {
    if (!elem) {
        return '(요소 없음)';
    }
    let userArr = elem.className.split(' ').filter(function (c) { return c.indexOf('cc_') === 0; });
    let cs = window.getComputedStyle(elem);

    return "설정 class = " + (userArr.length ? userArr.join(' ') : '없음')
        + " / 배경색 = " + cs.backgroundColor + " / 글자색 = " + cs.color;
}



// Column 영역별 class 적용 확인 (조건 미설정 시 출력과 대비)
//  - validation 1 : Header / Body / Footer Column 영역에 class 적용 ([렌더] 3줄)
//  - validation 2 : 공백으로 구분한 여러 클래스가 모두 적용 ([렌더] 설정 class 목록)
//  - validation 3 : style 블럭에 정의한 스타일이 화면에 반영 ([렌더] 배경색 / 글자색)
scwin.btn_checkClass_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");

    let cClass = con_class.getValue();
    let headTd = target1.render.querySelector("[id='" + target1.id + "_column1']");
    let bodyTd = document.querySelector("td[id*='target1_cell_0_0']");
    let footTd = target1.render.querySelector("[id='" + target1.id + "_footer_col1']");

    bottom.setReturnValue("[선언] column class : " + (cClass === '' ? '(미설정)' : cClass));
    bottom.setReturnValue("[렌더] Header column1 : " + scwin.getColumnInfo(headTd));
    bottom.setReturnValue("[렌더] Body col1 (Row 0) : " + scwin.getColumnInfo(bodyTd));
    bottom.setReturnValue("[렌더] Footer footer_col1 : " + scwin.getColumnInfo(footTd));
}
